+    <div class="alert alert-danger">@errorMessage</div>
+}
+
+<div class="row">
+    <!-- Sidebar Filters -->
+    <div class="col-3">
+        <CatalogFilters Categories="categories"
+                        OnFilterApplied="HandleFilterApplied"
+                        OnFilterCleared="HandleFilterCleared" />
+    </div>
+
+    <!-- Main Content -->
+    <div class="col-9">
+        @if (isLoading)
+        {
+            <div class="d-flex justify-content-center py-5">
+                <div class="spinner-border text-primary" role="status">
+                    <span class="visually-hidden">Loading...</span>
+                </div>
+            </div>
+        }
+        else if (result is not null && result.Items.Count == 0)
+        {
+            <div class="alert alert-info">No products found matching your criteria.</div>
+        }
+        else if (result is not null)
+        {
+            <CatalogToolbar SortBy="@sortBy"
+                            TotalCount="result.TotalCount"
+                            Page="result.Page"
+                            PageSize="result.PageSize"
+                            OnSortChanged="HandleSortChanged" />
+
+            <ProductGrid Products="result.Items"
+                         OnProductSelected="HandleProductSelected"
+                         OnAddToCart="HandleAddToCart" />
+
+            <div class="mt-4">
+                <CatalogPagination CurrentPage="currentPage"
+                                   TotalCount="result.TotalCount"
+                                   PageSize="pageSize"
+                                   OnPageChanged="HandlePageChanged" />
+            </div>
+        }
+    </div>
+</div>
+
+@code {
+    private List<string> categories = new();
+    private PagedResult<Product>? result;
+    private ProductFilter currentFilter = new(null, null, null, false);
+    private string sortBy = "price_asc";
+    private int currentPage = 1;
+    private int pageSize = 12;
+    private bool isLoading = true;
+    private string? errorMessage;
+
+    [Parameter]
+    public EventCallback<Product> OnProductSelected { get; set; }
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadDataAsync();
+    }
+
+    private async Task LoadDataAsync()
+    {
+        try
+        {
+            isLoading = true;
+            errorMessage = null;
+
+            var categoriesTask = ProductService.GetCategoriesAsync();
+            var searchTask = ProductService.SearchAsync(currentFilter, sortBy, currentPage, pageSize);
+
+            await Task.WhenAll(categoriesTask, searchTask);
+
+            categories = categoriesTask.Result;
+            result = searchTask.Result;
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load products: {ex.Message}";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private async Task SearchAsync()
+    {
+        try
+        {
+            isLoading = true;
+            errorMessage = null;
+            result = await ProductService.SearchAsync(currentFilter, sortBy, currentPage, pageSize);
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load products: {ex.Message}";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private async Task HandleFilterApplied(ProductFilter filter)
+    {
+        currentFilter = filter;
+        currentPage = 1;
+        await SearchAsync();
+    }
+
+    private async Task HandleFilterCleared()
+    {
+        currentFilter = new ProductFilter(null, null, null, false);
+        currentPage = 1;
+        await SearchAsync();
+    }
+
+    private async Task HandleSortChanged(string newSort)
+    {
+        sortBy = newSort;
+        currentPage = 1;
+        await SearchAsync();
+    }
+
+    private async Task HandlePageChanged(int page)
+    {
+        currentPage = page;
+        await SearchAsync();
+    }
+
+    private async Task HandleProductSelected(Product product)
+    {
+        await OnProductSelected.InvokeAsync(product);
+    }
+
+    private Task HandleAddToCart(Product product)
+    {
+        // Placeholder for cart functionality
+        return Task.CompletedTask;
+    }
+}
+

